-- STALE-PR-CONFLICT-REPAIR-1 and MERGEABILITY-NUDGE-1 (2026-10-12, pillar autonomy; agent_issues 2304 and 2230). Carries the
-- migration of PR 910 (migrations/2026-10-11-conflict-repair-failure-mode.sql, never merged) and adds the second failure mode.
-- 1. pr-conflict-silent-close: PR 870 (qnfo-ai ACCURACY-GROUND-1) had every check green and sat 26h because main moved under it
--    (mergeable_state dirty); no lane merges or repairs a conflicting PR, so CYCLE-TIME-1 closed it unmerged and nobody was told.
--    qnfo-fleet-control 0.17.0 files one repair issue per such PR. The detector reads the closer's own log: a PR closed with
--    "mergeable_state dirty" in its reason and no conflict-repair-issue row for the same PR. Closures before 2026-10-12T12:00Z
--    are excluded (PR 870 was re-applied as PR 905; PR 910 is superseded by the PR that carries this file).
-- 2. pr-null-mergeable-silent-skip: PR 834 (2026-10-09) was green and quiet, GitHub left mergeable null, and the lane skipped it
--    with no row. 0.17.0 asks GitHub to bring the branch up to date and logs every non-merge. The detector: no PR closed
--    unmerged in 48h whose reason says mergeable null without a merge-nudge row for that PR.
-- 3. control_registry rows for the two kill switches the worker gains (doctrine section 11): each stops an enhancer layered on
--    the merge lane, never the lane itself.
-- Not registered on purpose: workflow (.github/) PRs are never auto-merged by design (security precedence, CLAUDE.md); that is a
-- limit, not a failure, and D1 cannot see an open PR, so a detector for it would pass while the wait happens.
-- Idempotent (INSERT OR IGNORE).
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DELETE FROM remediation_contracts WHERE class IN ('fm-pr-conflict-silent-close', 'fm-pr-null-mergeable-silent-skip'); DELETE FROM failure_modes WHERE fm_key IN ('pr-conflict-silent-close', 'pr-null-mergeable-silent-skip'); DELETE FROM control_registry WHERE control IN ('stale-pr-nudge-switch', 'stale-pr-conflict-repair-switch');
INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius) VALUES
 ('pr-conflict-silent-close', 'a green session pull request that conflicts with main is closed unmerged with no repair issue', 'STALE-PR-MERGE-FIRST-1 merges only mergeable_state clean and STALE-PR-CHECK-REPAIR-1 repairs only a failing non-required check, so a dirty PR matched no lane and CYCLE-TIME-1 closed it at 24h', 'qnfo-fleet-control 0.17.0 STALE-PR-CONFLICT-REPAIR-1 files a deduped high-priority issue with the re-apply procedure when a quiet PR is dirty', 'no close-stale-pr row with mergeable_state dirty lacks a conflict-repair-issue row for the same PR', 'fm-pr-conflict-silent-close', '2026-10-10', 2304, 'main changes a file a quiet session PR also changes', 'a branch_hygiene_log close-stale-pr row whose reason says mergeable_state dirty', 'every session PR that is open when main moves under it; its work leaves the merge queue'),
 ('pr-null-mergeable-silent-skip', 'a green quiet session pull request is skipped by the merge lane because GitHub never computes its mergeability, with no log row', 'GitHub computes mergeable lazily and can leave it null; bhTryMerge re-read three times and refused, and branchHygieneTick wrote no row for a refusal under 24h', 'qnfo-fleet-control 0.17.0 MERGEABILITY-NUDGE-1 asks GitHub to bring the branch up to date (at most 3 times in 24h) and MERGE-REFUSAL-LOG-1 writes merge-nudge or merge-refused for every non-merge', 'no close-stale-pr row in 48h says mergeable null without a merge-nudge row for the same PR', 'fm-pr-null-mergeable-silent-skip', '2026-10-09', 2230, 'GitHub leaves mergeable null on an open pull request', 'merged_prs 0 on a tick while a green PR older than 2h is open, and no branch_hygiene_log row for it', 'any session PR; its merge waits until someone reads the PR page or it is closed at 24h');
INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, budget_ms, max_items, requires_container) VALUES
 ('fm-pr-conflict-silent-close', NULL, 'STALE-PR-CONFLICT-REPAIR-1', 'failure-mode detector', 'SELECT ''1'' AS expected, CASE WHEN (SELECT COUNT(*) FROM branch_hygiene_log c WHERE c.action = ''close-stale-pr'' AND c.dry = 0 AND c.ok = 1 AND c.why LIKE ''%mergeable_state dirty%'' AND c.ts > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-48 hours'') AND c.ts > ''2026-10-12T12:00:00Z'' AND NOT EXISTS (SELECT 1 FROM branch_hygiene_log r WHERE r.action = ''conflict-repair-issue'' AND r.pr = c.pr)) = 0 THEN ''1'' ELSE ''0'' END AS observed', 'd1-query', 3, 'qnfo-fleet-control', 1, 'holding', 'failure-mode', 45000, 5, 0),
 ('fm-pr-null-mergeable-silent-skip', NULL, 'MERGEABILITY-NUDGE-1', 'failure-mode detector', 'SELECT ''1'' AS expected, CASE WHEN (SELECT COUNT(*) FROM branch_hygiene_log c WHERE c.action = ''close-stale-pr'' AND c.dry = 0 AND c.ok = 1 AND c.why LIKE ''%mergeable null%'' AND c.ts > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-48 hours'') AND c.ts > ''2026-10-12T12:00:00Z'' AND NOT EXISTS (SELECT 1 FROM branch_hygiene_log r WHERE r.action = ''merge-nudge'' AND r.pr = c.pr)) = 0 THEN ''1'' ELSE ''0'' END AS observed', 'd1-query', 3, 'qnfo-fleet-control', 1, 'holding', 'failure-mode', 45000, 5, 0);
INSERT OR IGNORE INTO control_registry (control, location, kind, guards_against, critical_path, disposition, disposition_state, alternate_path, alternate_tested_at, evidence, issue_id) VALUES
 ('stale-pr-nudge-switch', 'ops_config stale_pr_nudge_enabled (absent = on), read by qnfo-fleet-control bhConfig', 'kill-switch', 'a branch brought up to date from main when that is not wanted (checks run again, the head moves)', 0, 'keep', 'applied', 'off restores the refusal, which MERGE-REFUSAL-LOG-1 still logs; the merge lane itself is unchanged', '2026-10-12', 'qnfo-fleet-control/branch-hygiene.test.mjs: the switch off makes no update-branch call and writes one merge-refused row; the nudge is capped at 3 per PR in 24h', 2230),
 ('stale-pr-conflict-repair-switch', 'ops_config stale_pr_conflict_repair_enabled (absent = on), read by qnfo-fleet-control bhConfig', 'kill-switch', 'repair issues filed for conflicting pull requests when nobody should act on them', 0, 'keep', 'applied', 'off files nothing; the refusal is still a merge-refused row and CYCLE-TIME-1 closes the PR with the reason', '2026-10-12', 'qnfo-fleet-control/branch-hygiene.test.mjs: the switch off files no issue and the refusal is still logged', 2304);
